#define SW_RAC4_SITE_CRASH_BOT_ADDR 0x008088ECu
#define SW_RAC4_SITE_CRASH_BOT 0x4BE5F45Cu

/* tod: its flag bytes, then its sites */
#define SW_TOD_FLAG_FAST_LOADS 0x108A8560u
#define SW_TOD_FLAG_INFINITE_AMMO 0x108A8561u
#define SW_TOD_DATA_FMV_IN 0x108A8564u
#define SW_TOD_SITE_FAST_LOADS_ADDR 0x0025E588u
#define SW_TOD_SITE_FAST_LOADS 0x4818CFF0u
#define SW_TOD_SITE_OWN_DEPARTURE_ADDR 0x003C5744u
#define SW_TOD_SITE_OWN_DEPARTURE 0x48025EB4u
#define SW_TOD_SITE_OWN_FMV_CUT_ADDR 0x003C57DCu
#define SW_TOD_SITE_OWN_FMV_CUT 0x48025E7Cu
#define SW_TOD_SITE_OWN_FMV_IN_ADDR 0x003C58C8u
#define SW_TOD_SITE_OWN_FMV_IN 0x48025E08u
#define SW_TOD_SITE_INFINITE_AMMO_ADDR 0x0049EF08u
#define SW_TOD_SITE_INFINITE_AMMO 0x4BF4C7EDu

/* One trampoline, or the one piece of data a trampoline reads. */
struct sw_cave {
	u32 addr;
	const u8 *bytes;
	u32 len;
};

/*
 * Revision 1.24: the pieces named own_*, which a console writes itself
 * (switches_own.c, the one part of the switches the SPRX links): the caves,
 * then the sites, each in address order, the same bytes as the patch's.
 */
#define SW_RAC4_OWN_NCAVES 1
#define SW_RAC4_OWN_NSITES 4
extern const struct sw_cave sw_rac4_own_caves[];
extern const struct patch_word sw_rac4_own_sites[];
#define SW_TOD_OWN_NCAVES 1
#define SW_TOD_OWN_NSITES 3
extern const struct sw_cave sw_tod_own_caves[];
extern const struct patch_word sw_tod_own_sites[];

/*
 * Everything one game's switches are: the caves, the site words that branch
 * into them, and the flag bytes they read. All three are in address order.
 */
struct sw_desc {
	u8 game_id;

	const struct sw_cave *caves;
	u8 ncaves;

	const struct patch_word *sites;
	u8 nsites;

	const u32 *flags;
	u8 nflags;
};

/* NULL for a game with no switches, and for GAME_NONE. */
const struct sw_desc *sw_desc_for_game(u8 game_id);

#endif /* QWARK_SWITCHES_BINS_H */
